const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const progress=(n,color='var(--accent)')=>`<div class="progress"><span style="width:${n}%;background:${color}"></span></div>`;
const head=(title,sub='',right='')=>`<div class="panel-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;
const section=(title,right='')=>`<div class="section-head"><h2>${title}</h2>${right}</div>`;
const action=(label,act,cls='text-button')=>`<button class="${cls}" data-action="${act}">${label}</button>`;
const summary=items=>`<div class="summary-strip">${items.map(([label,value,cls=''])=>`<div><small>${label}</small><strong class="${cls}">${value}</strong></div>`).join('')}</div>`;
const metric=(title,value,sub,tag='',coin='')=>`<div class="panel metric"><div class="metric-top">${coin?`<span class="coin-icon">${coin}</span>`:title}${tag?badge(tag):''}</div>${coin?`<p class="muted small" style="margin-bottom:6px">${title}</p>`:''}<strong>${value}</strong><small>${sub}</small></div>`;
function chart(kind='smooth',cls='',label='Monthly financial performance'){
 const growth=kind==='growth',portfolio=kind==='portfolio',offset=period==='1M'?20:period==='1Y'?-18:0;
 const first=portfolio?'M15 178 C70 165 83 135 132 142 S203 97 253 105 S326 67 382 55 S434 28 455 22':growth?'M15 202 C78 164 102 155 158 170 S249 172 286 82 S350 -5 382 83 S436 112 455 22':`M15 ${130+offset} C65 135 85 162 132 137 S182 73 230 112 S290 158 337 115 S389 91 422 103 S446 111 455 108`;
 const second=growth?'M15 194 C95 169 130 119 190 127 S273 137 318 100 S399 -1 455 25':'M15 137 C77 146 101 155 147 131 S212 136 252 120 S298 87 334 107 S386 145 422 132 S450 131 455 135';
 return `<svg class="chart ${cls}" viewBox="0 0 470 240" role="img" aria-label="${label}" preserveAspectRatio="none"><defs><linearGradient id="area-${kind}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${portfolio?'#49d5b0':'var(--accent)'}" stop-opacity=".28"/><stop offset="1" stop-color="${portfolio?'#49d5b0':'var(--accent)'}" stop-opacity="0"/></linearGradient></defs>${[50,100,150,200].map(y=>`<path class="grid-line" d="M15 ${y}H455"/>`).join('')}<path d="${first} L455 215H15Z" fill="url(#area-${kind})"/>${!portfolio?`<path class="line-secondary" style="${growth?'stroke:var(--purple);opacity:1':''}" d="${second}"/>`:''}<path class="line-main" style="${portfolio?'stroke:var(--green)':''}" d="${first}"/>${!growth&&!portfolio?`<path d="M192 65v135" stroke="#ffffff15" stroke-dasharray="3 4"/><circle class="chart-point" cx="192" cy="104" r="4"/><g class="chart-tooltip" transform="translate(161 54)"><rect width="66" height="30" rx="9"/><text x="33" y="19" text-anchor="middle">$45.87</text></g>`:`<circle class="chart-point" cx="455" cy="${portfolio?22:22}" r="4"/>`}${(portfolio?['May','Jun','Jul','Aug','Sep','Oct']:['Jan','Feb','Mar','Apr','May','Jun']).map((v,i)=>`<text x="${15+i*88}" y="236" text-anchor="${i===0?'start':i===5?'end':'middle'}">${v}</text>`).join('')}</svg>`;
}
function profile(){return `<div class="profile-toolbar"><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><button class="icon-button" data-page="settings" aria-label="Profile settings">⋮</button></div><div class="profile"><span class="avatar">${escapeHtml(prefs.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><p>Exclusive Card</p><h3>${escapeHtml(prefs.name)}</h3><span class="member">GLASSY PRIVATE MEMBER</span></div><div class="quick-actions">${[['Transfer','arrow'],['Receive','receive'],['Bill','file'],['Top Up','card']].map(([name,i])=>`<button class="quick-action" data-action="${name.toLowerCase().replace(' ','-')}"><span>${icon(i)}</span>${name}</button>`).join('')}</div><div class="bank-card"><div class="card-top"><span class="visa">VISA</span><span class="chip"></span></div><small>Total Balance</small><strong>$678,993.98</strong><div class="card-bottom"><span>•••• 8824</span><span>09/28</span></div></div><h3 class="side-title">Last Transaction</h3><div class="transaction-small"><span class="mini-avatar">GA</span><div><strong>Gojo Ackerman</strong><small>Today, 10:02 AM</small></div>${badge('+$900','orange')}</div><button class="side-link" data-page="transactions">See all transactions ${icon('right')}</button><p class="secure-note">${icon('lock')} Your space. Safely on this device.</p>`}
function dashboard(){return `${summary([['Total Balance','$678,993.98'],['Total Income','$998,993.98'],['Expenses','$28,993.98']])}${section('Statistic',`<select id="chart-type" class="pill" aria-label="Transaction chart"><option>All Transactions</option><option${chartType==='Income'?' selected':''}>Income</option><option${chartType==='Expenses'?' selected':''}>Expenses</option></select>`)}<div class="panel dashboard-chart">${head('Top Contributor',`${chartType==='All Transactions'?'Track your earning and expenses':chartType+' overview'} over time`,`<div class="legend"><span>Groceries</span><span>Invest Corporate</span><span>Hobbies</span></div>`)}${chart()}<div class="component-group" style="margin:0 0 4px;justify-content:flex-end">${['1M','6M','1Y'].map(x=>`<button class="pill" data-period="${x}" style="${period===x?'color:var(--accent)':''}">${x}</button>`).join('')}</div></div>${section('Goals & savings',action('Add goal +','add-goal'))}<div class="grid dashboard-bottom"><div class="panel goal-card"><div class="goal-top"><span class="value">78%</span>${icon('home')}</div>${progress(78)}<p>Build a house</p></div><div class="panel goal-card"><div class="goal-top"><span class="value">97%</span>${icon('heart')}</div>${progress(97)}<p>Wedding savings</p></div><div class="panel savings"><div><small class="muted">Business Savings</small><strong><em>$</em> 439,283.0</strong>${badge('↗ 49.3%')}</div><div class="bar-chart">${[28,47,66].map((h,i)=>`<div><i style="height:${h}px;animation-delay:${i*.1}s"></i><small>${['Feb','Mar','Apr'][i]}</small></div>`).join('')}</div></div></div>${customGoals.length?`<div class="grid three spaced">${customGoals.map(g=>`<div class="panel goal-card"><div class="goal-top"><span class="value">${Math.round(g.saved/g.target*100)}%</span>${icon('star')}</div>${progress(Math.min(100,g.saved/g.target*100))}<p>${escapeHtml(g.name)} · ${money(g.saved)} / ${money(g.target)}</p></div>`).join('')}</div>`:''}<div class="panel activity-strip">${icon('bolt')}<span>Your savings grew <strong>12.8%</strong> this month.</span>${badge('On track')}</div>`}
function cards(){let c=cardSettings[selectedCard];return `${summary([['Credit Available','$150,000.00'],['Active Cards','3 Virtual & Metal'],['Monthly Spend','$15,250.20']])}<div class="grid three credit-cards">${[['World Elite Mastercard','MASTERCARD','8824','84,250.00','Black Obsidian Metal','09/28',''],['Platinum Visa Business','VISA','4190','42,800.50','Emerald Corporate','11/27','emerald'],['Instant Digital Card','VISA','9032','6,450.00','Virtual Cyber Card','04/29','violet']].map((x,i)=>`<button class="credit-card ${x[6]} ${i===selectedCard?'selected':''}" data-card="${i}" aria-pressed="${i===selectedCard}"><div class="card-name">${x[0]}<b>${x[1]}</b></div><div><div class="number">•••• •••• •••• ${x[2]}</div><div class="balance">$${x[3]}</div></div><div class="card-expiry"><span>${x[4]}</span><span>${x[5]}</span></div></button>`).join('')}</div><div class="grid two spaced"><div class="panel">${head('Card Security & Limits',['Black Obsidian Metal (8824)','Emerald Corporate (4190)','Virtual Cyber Card (9032)'][selectedCard],badge('◉ Active'))}<label class="range-label" for="spending-limit">Monthly Spending Limit <b id="limit-value">${money(c.limit)}</b></label><input id="spending-limit" type="range" min="1000" max="50000" step="500" value="${c.limit}"><label class="setting-row"><span><strong>Online Purchases</strong><p>E-commerce & subscriptions</p></span><input class="switch" data-card-setting="online" type="checkbox" ${c.online?'checked':''}></label><label class="setting-row"><span><strong>International Payments</strong><p>Zero FX transaction fees</p></span><input class="switch" data-card-setting="international" type="checkbox" ${c.international?'checked':''}></label></div><div class="panel">${head('Spending by Category','Current billing cycle',badge('+12.4% vs last mo'))}${[['Luxury Shopping','$4,420',44,'var(--accent)'],['Travel & Flights','$3,850',32,'var(--green)'],['Dining & Club','$2,440',23,'var(--purple)'],['Tech & Software','$2,340',19,'#48c398']].map(([name,amount,n,color])=>`<div class="spending-row"><div><span class="muted">${name}</span><b>${amount}</b></div>${progress(n,color)}</div>`).join('')}</div></div>${section('Recent Card Activity')}<div class="grid three activity-cards">${[['bag','Apple Store Regent St','Electronics · Today','$1,299.00'],['plane','Emirates First Class','Travel · Yesterday','$4,850.00'],['star','Nobu Restaurant','Fine dining · Oct 08','$440.20']].map(([i,n,d,a])=>`<div class="panel activity-card">${icon(i)}<div><strong>${n}</strong><small>${d}</small></div>${badge(a,'red')}</div>`).join('')}</div>`}
function wallet(){return `${summary([['Total Portfolio','$1,428,990.00'],['24h Change','+$14,280 (+3.2%)','positive'],['Staking APY','8.4% Fixed']])}<div class="grid four">${metric('Bitcoin','$420,000','4.58 BTC','+4.8%','₿')}${metric('Ethereum','$185,000','52.11 ETH','+3.2%','Ξ')}${metric('Solana','$68,400','450.00 SOL','+8.7%','◎')}${metric('USD Treasury','$755,590','755,590 USD','+0.1%','$')}</div><div class="grid two spaced"><div class="panel">${head('Portfolio Capital Growth','Cumulative returns · last 6 months',badge('+34.8% YTD'))}${chart('portfolio','growth-chart','Portfolio capital growth over six months')}</div><div class="panel">${head('Instant Swap','Simulated exchange · demo rates',`<i class="online"></i>`)}<label class="field"><span>You Pay</span><span class="field-line"><input id="swap-pay" type="number" min="1" step="any" value="5000" aria-label="Amount to exchange"><select id="swap-from" aria-label="Source currency"><option>USD</option><option>BTC</option><option>ETH</option><option>SOL</option></select></span></label><button class="swap-direction" data-action="reverse-swap" aria-label="Reverse currencies">⇅</button><label class="field"><span>You Receive (Est.)</span><span class="field-line"><input id="swap-receive" value="0.0543" readonly aria-label="Estimated received amount"><select id="swap-to" aria-label="Target currency"><option>BTC</option><option>ETH</option><option>SOL</option><option>USD</option></select></span></label><button class="primary full" data-action="swap">Confirm Instant Exchange</button><p class="muted" style="font-size:8px;text-align:center;margin-top:10px">Demo only · no real funds are moved</p></div></div>`}
function documents(){let filtered=docs.filter(d=>docFilter==='All Documents'||d.category===docFilter);return `${summary([['Tax Deduction Claimed','$268,850.00'],['Tax Deductions','$42,300.00'],['Compliance Status','100% Verified']])}<div class="tabs">${['All Documents','Tax Filings','Bank Statements','Expense Invoices'].map(t=>`<button data-doc-filter="${t}" class="${t===docFilter?'active':''}">${t}</button>`).join('')}</div><div class="panel">${head('Audit Trail & Digital Records','Local documents & downloadable demo records',action('+ Upload New Document','upload-document'))}<div class="document-list">${filtered.map(d=>`<div class="document-row">${icon('file')}<div class="doc-info"><strong>${escapeHtml(d.name)}</strong><small>${d.date} · ${d.size}</small></div>${badge(d.status)}<span class="doc-amount">${money(d.amount)}</span><button class="icon-button" data-document="${docs.indexOf(d)}" aria-label="Download ${escapeHtml(d.name)}">${icon('download')}</button></div>`).join('')||'<div class="empty-state">No documents in this category.</div>'}</div></div><div class="panel activity-strip">${icon('lock')}<span>Files you add stay on your device. No server uploads.</span></div>`}
function transactionPage(){return `${summary([['Income',money(transactions.filter(t=>t.amount>0).reduce((a,t)=>a+t.amount,0))],['Expenses',money(-transactions.filter(t=>t.amount<0).reduce((a,t)=>a+t.amount,0))],['Transactions',String(transactions.length)]])}<div class="panel">${head('Your recent activity','All demo transactions in one place',action('Export CSV','export-transactions','secondary'))}<label class="field"><span>Search transactions</span><input id="transaction-search" type="search" placeholder="Name, category or amount…" style="font-size:12px"></label><div id="transaction-list">${transactionRows(transactions)}</div></div>`}
function transactionRows(list){return list.map(t=>`<div class="earning"><span class="earning-icon">${icon(t.amount>0?'receive':'arrow')}</span><div><strong>${escapeHtml(t.name)}</strong><p>${escapeHtml(t.detail)}</p></div><div class="earning-amount"><strong class="${t.amount>0?'positive':''}">${t.amount>0?'+':''}${money(t.amount)}</strong><p>${t.type}</p></div></div>`).join('')||'<p class="empty-state">No transactions found.</p>'}
function videoTable(full=false){let list=videos.filter(v=>videoFilter==='All'||v.category===videoFilter);return `<div class="table-wrap"><table><thead><tr><th>Video ${full?'Details':''}</th>${full?'<th>Category</th>':''}<th>Views</th>${full?'<th>CTR</th>':''}<th>${full?'Avg. Retention':'Average view duration'}</th><th>${full?'Est. Revenue':'Trend'}</th><th></th></tr></thead><tbody>${list.slice(0,full?100:2).map((v,i)=>`<tr><td><strong>${!full?'<img src="assets/uncharted.jpg" class="thumb" alt="">':''}${escapeHtml(v.title)}</strong><span class="muted">${full?'Published · Oct '+(9-i*2):v.category}</span></td>${full?`<td>${v.category}</td>`:''}<td>${v.views}</td>${full?`<td>${v.ctr}</td>`:''}<td>${v.retention}</td><td>${full?money(v.revenue):`<svg viewBox="0 0 100 30" style="width:72px;color:${i?'var(--green)':'var(--accent)'}"><path d="M2 21Q15 4 25 17T50 14 70 12 87 20L96 8"/></svg>`}</td><td><button class="text-button" data-video="${videos.indexOf(v)}" aria-label="Details for ${escapeHtml(v.title)}">•••</button></td></tr>`).join('')}</tbody></table></div>`}
function analytics(){return `<div class="grid hero-split"><div class="panel creator-hero"><img src="assets/creator.jpg" alt="Creator wearing an orange jacket"><div class="hero-copy"><p class="subtitle">Popular Solution</p><h2>Optimize<br>Your Metrics</h2><button class="white-button" data-page="studio">Start Now</button></div><div class="creator-metrics">${[['76k','Users'],['1.5m','Clicks'],['$3.6k','Sales'],['47','Items']].map(([n,t])=>`<div><strong>${n}</strong><small>${t}</small></div>`).join('')}</div></div><div class="stack"><div class="panel">${head('Active Users right now', '',badge('● 50 online'))}${chart('smooth','mini-chart','Active users over time')}</div><div class="panel">${head('Latest Sales','',badge('+4%'))}<div class="latest-sale"><div><strong><span class="positive">$</span> 586</strong><p class="subtitle">Your total earnings</p></div><div style="text-align:center"><div class="product-shape" style="margin:auto"></div><p class="subtitle" style="font-size:8px">Synthetics backpack</p></div></div></div></div></div><div class="panel spaced">${head('Your top videos in this period','',action('View all →','view-studio'))}${videoTable()}</div>`}
function studio(){return `<div class="grid four">${metric('Total Uploads',`${84+videos.length-4} Videos`,'4 published this week','+12%')}${metric('Average Retention','34.8%','+4.2% vs previous month')}${metric('Click-Through Rate','12.4%','High-performance thumbnails','Top 5%')}${metric('Estimated Ad Revenue','$1,590','Across top 4 videos')}</div><div class="panel spaced">${head('Video Performance & Retention','',action('+ Upload Video','upload-video','white-button'))}<div class="tabs">${['All','Sport Series','Nutrition'].map(t=>`<button data-video-filter="${t}" class="${videoFilter===t?'active':''}">${t}</button>`).join('')}</div>${videoTable(true)}</div><div class="grid two spaced"><div class="panel">${head('Publishing cadence','Stay consistent. Keep growing.',badge('4 / 5 this week'))}${progress(80)}<p class="subtitle">One more upload to reach your weekly goal.</p></div><div class="panel">${head('Your next idea','Turn an idea into your next best video.')}${action('Create a content task →','content-task','secondary')}</div></div>`}
function growth(){return `<div class="grid hero-split"><div class="panel">${head('Audience Velocity & Impression Surge','REAL-TIME GROWTH',`<select id="growth-period" class="pill" aria-label="Growth period">${['1M','6M','1Y'].map(p=>`<option ${period===p?'selected':''}>${p}</option>`).join('')}</select>`)}${chart('growth','growth-chart','Current and previous period audience growth')}<div class="legend"><span>Current period (${period==='1M'?'254k':period==='1Y'?'3.2m':'1.5m'} views)</span><span>Previous period</span></div></div><div class="panel">${head('Traffic Sources','Where your viewers discover you')}${[['YouTube Search',48,'var(--accent)'],['Suggested Videos',32,'#d86c9d'],['External & Social',12,'#65c8eb'],['Direct & Channel Pages',8,'var(--green)']].map(([n,v,c])=>`<div class="spending-row"><div><span>${n}</span><b>${v}%</b></div>${progress(v,c)}</div>`).join('')}<div class="panel activity-strip" style="margin-top:28px;padding:12px;font-size:9px">${icon('chart')}<span>Search discovery is up <b>18.4%</b></span></div></div></div><div class="panel spaced">${head('Geographic Audience Reach','Your community around the world',badge('142 countries','orange'))}<div class="country-grid">${[['🇺🇸','United States',42],['🇬🇧','United Kingdom',18],['🇮🇳','India',22],['🇩🇪','Germany',11],['🇨🇦','Canada',7]].map(([f,n,v])=>`<div><strong>${f}</strong><p>${n}</p>${progress(v*2)}<b>${v}%</b></div>`).join('')}</div></div>`}
function revenue(){return `<div class="panel balance-hero"><div class="panel-head"><div>${badge('TOTAL CHANNEL BALANCE')}<strong>${money(3620-withdrawn)}</strong></div>${action('Withdraw Funds','withdraw','primary')}</div><div class="grid three revenue-stats"><div><p>Available for payout</p><strong>${money(586-withdrawn)}</strong><p>Next payout · tomorrow</p></div><div><p>30-Day Estimated RPM</p><strong>$4.82</strong><p>+14% vs last period</p></div><div><p>Synthetics Merch Revenue</p><strong>$1,172.00</strong><p>47 units sold</p></div></div></div><div class="panel spaced">${head('Recent Earnings & Payouts','',`<span class="muted small">October 2026</span>`)}${[['bag','Synthetics Backpack Sales (8 units)','Today, 11:20 AM · TX-9821',586],['play','YouTube Partner AdSense Rev Share','Yesterday · TX-9820',2450],['star','Brand Sponsorship · GymWear Co','Oct 02, 2026 · TX-9819',584],['users','Direct Creator Channel Memberships','Sep 28, 2026 · TX-9818',280],...(withdrawn?[['arrow','Demo payout requested','Local simulation',-withdrawn]]:[])].map(([i,n,d,a])=>`<div class="earning"><span class="earning-icon">${icon(i)}</span><div><strong>${n}</strong><p>${d}</p></div><div class="earning-amount"><strong>${a>0?'+':''}${money(a)}</strong><p>${a>0?'Completed':'Simulated'}</p></div></div>`).join('')}</div>`}
const games=[{name:'Uncharted 4',img:'uncharted',genre:'Adventure',hours:24},{name:'Dishonored: Standard Edition',img:'dishonored',genre:'Action',hours:38},{name:'Elden Ring',img:'elden-ring',genre:'RPG',hours:112}];
function gameCards(list=games){return `<div class="grid three game-cards">${list.map(g=>`<button class="game-card" data-game="${escapeHtml(g.name)}"><img src="assets/${g.img}.jpg" alt="${escapeHtml(g.name)} artwork"><span class="play-icon">${icon('play')}</span><strong>${g.name}</strong></button>`).join('')}</div>`}
function gaming(){return `<div class="grid hero-split"><div class="panel game-hero"><img src="assets/valorant.jpg" alt="Valorant character artwork"><div class="hero-copy">${badge('🔥 Popular','orange')}<h2>Valorant</h2><p>A competitive world, a fearless squad.<br>Your next great play starts here.</p><button class="white-button" data-game="Valorant">${'▶'} Explore game</button></div></div><div class="game-list">${[['🧶','Unravel 2','Unbound Edition · Starter Pack'],['🏄','Subway Surf','Endless World Tour Arcade'],['🌅','Red Dead Redemption 3','Premium Pack · Concept']].map(([i,n,d])=>`<button data-game="${n}"><span class="game-icon">${i}</span><span><strong>${n}</strong><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</div></div><div class="grid hero-split spaced"><div>${section('New Games',`<button class="text-button" data-page="library">See more →</button>`)}${gameCards()}</div><div class="panel">${head('Your Statistic','',icon('right'))}<div class="orb-wrap"><div class="orb"><div class="orb-center"><small>TOTAL HOURS</small><strong>12,340h</strong></div></div></div><div class="game-stats">${[['↗','2,340h','var(--accent)'],['◉','5,420h','#d9d3e1'],['✦','4,580h','#8770f4']].map(([i,h,c])=>`<div><i style="background:${c}">${i}</i><strong>${h}</strong></div>`).join('')}</div></div></div>${section('Last Downloads')}<div class="panel download-row"><span class="game-icon" style="font-size:12px;font-weight:800;background:#eeebe3;color:#151515">FIFA<br>23</span><div class="download-info"><strong>FIFA 23</strong><small>Sports simulator · <span id="download-percent">${downloadProgress}</span>%</small><div class="progress"><span id="download-bar" style="width:${downloadProgress}%"></span></div></div><small id="download-status">${downloadProgress===100?'Ready to play':downloadPaused?'Paused':'Downloading…'}</small><button class="icon-button" data-action="download-toggle" aria-label="Pause or resume download">${icon(downloadPaused?'play':'clock')}</button></div>`}
function library(){return `${section('Your collection',`<span class="badge orange">${games.length+1} games</span>`)}<div class="tabs">${['All games','Adventure','Action','RPG'].map(t=>`<button data-game-filter="${t}" class="${gameFilter===t?'active':''}">${t}</button>`).join('')}</div>${gameCards(games.filter(g=>gameFilter==='All games'||g.genre===gameFilter))}<div class="grid two spaced"><div class="panel">${head('Jump back in','Your last session is waiting')}<div class="earning"><span class="game-icon">✦</span><div><strong>Elden Ring</strong><p>Level 84 · 112 hours played</p></div><button class="primary" style="margin-left:auto" data-game="Elden Ring">Continue</button></div></div><div class="panel">${head('Friends online','A good game is better together',badge('4 online'))}<div class="friends">${['AK','JN','MS','DL'].map(n=>`<button class="friend text-button" data-friend="${n}"><span class="mini-avatar">${n}</span></button>`).join('')}</div></div></div>`}
function achievements(){return `${summary([['Unlocked','24 / 40'],['Total XP','18,450'],['Current Streak','7 days 🔥']])}<div class="grid three">${[['star','First Light','Complete your first adventure','Unlocked'],['bolt','On a Roll','Play for seven days in a row','Unlocked'],['users','Better Together','Join a squad of four friends','Unlocked'],['globe','World Explorer','Discover 100 locations','72 / 100'],['gift','Collector','Unlock 40 achievements','24 / 40'],['moon','Night Owl','Complete 20 evening sessions','12 / 20']].map(([i,n,d,s],idx)=>`<div class="panel" style="text-align:center;padding:30px 18px"><span class="game-icon" style="margin:0 auto 17px">${icon(i)}</span><h3>${n}</h3><p class="subtitle" style="margin:9px 0 20px">${d}</p>${badge(s,idx<3?'orange':'purple')}</div>`).join('')}</div>`}
function taskPage(){return `${summary([['Total Tasks',String(tasks.length)],['In Progress',String(tasks.filter(t=>t.status==='progress').length)],['Completed',String(tasks.filter(t=>t.status==='done').length)]])}${section('Make room for great work.',action('+ New task','add-task','primary'))}<div class="grid three task-board">${[['todo','To do'],['progress','In progress'],['done','Done']].map(([status,title])=>`<div class="panel task-col" data-status="${status}"><h3>${title}<span class="badge ${status==='done'?'':'orange'}">${tasks.filter(t=>t.status===status).length}</span></h3>${tasks.filter(t=>t.status===status).map(t=>`<article class="task-card" draggable="true" data-task="${t.id}">${badge(escapeHtml(t.tag),t.tag==='Design'?'purple':'orange')}<strong>${escapeHtml(t.title)}</strong><p>${escapeHtml(t.description)}</p><div class="task-footer"><small class="muted">${escapeHtml(t.date)}</small><select data-task-status="${t.id}" aria-label="Status for ${escapeHtml(t.title)}">${[['todo','To do'],['progress','In progress'],['done','Done']].map(([v,n])=>`<option value="${v}" ${t.status===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="text-button" style="margin-top:10px;font-size:8px" data-delete-task="${t.id}">Delete task</button></article>`).join('')||'<div class="empty-state">Drop a task here</div>'}</div>`).join('')}</div>`}
function calendarPage(){const first=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),dateKey=`${year}-${String(month+1).padStart(2,'0')}-${String(selectedDay).padStart(2,'0')}`,monthName=new Date(year,month,1).toLocaleString('en-US',{month:'long'}),list=events.filter(e=>e.date===dateKey).sort((a,b)=>a.time.localeCompare(b.time));return `<div class="panel"><div class="panel-head calendar-header"><div><p class="eyebrow">A LITTLE SPACE FOR EVERYTHING</p><h2>${monthName} ${year}</h2></div><div style="display:flex;gap:7px"><button class="icon-button" data-month="-1" aria-label="Previous month">‹</button><button class="icon-button" data-month="1" aria-label="Next month">›</button>${action('+ Event','add-event','primary')}</div></div><div class="calendar-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:Math.ceil((days+first)/7)*7},(_,i)=>{let day=i-first+1,key=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,event=events.find(e=>e.date===key);return day<1||day>days?'<span class="calendar-day outside"></span>':`<button class="calendar-day ${day===10&&month===9&&year===2026?'today':''} ${day===selectedDay?'selected':''}" data-day="${day}">${day}${event?`<span class="event-dot">${escapeHtml(event.title)}</span>`:''}</button>`}).join('')}</div></div><div class="panel spaced">${head(`Agenda · ${monthName} ${selectedDay}`,'Your moments, thoughtfully planned')}${list.map(e=>`<div class="earning"><span class="earning-icon">${icon('calendar')}</span><div><strong>${escapeHtml(e.title)}</strong><p>${e.time} · ${escapeHtml(e.type)}</p></div><button class="text-button" style="margin-left:auto" data-delete-event="${e.id}">Remove</button></div>`).join('')||'<div class="empty-state">A little breathing room. No events planned.</div>'}</div>`}
const colors=['#ff7629','#ed5c88','#a38aff','#5b9dff','#42c9b0','#e1bc62'];
function colorControls(){return `<div class="color-palette">${colors.map(c=>`<button class="swatch ${prefs.accent.toLowerCase()===c?'selected':''}" style="--swatch:${c}" data-color="${c}" aria-label="Accent color ${c}" aria-pressed="${prefs.accent.toLowerCase()===c}"></button>`).join('')}<input type="color" class="custom-color" data-custom-accent="true" value="${prefs.accent}" aria-label="Custom accent color"></div>`}
function components(){return `${section('Small details. A whole new feeling.',badge('Interactive collection','orange'))}<div class="grid two"><div class="panel">${head('Buttons & actions','Soft edges, subtle depth, immediate feedback.')}<div class="component-group"><button class="primary" data-action="demo-save">Save changes</button><button class="secondary" data-action="notifications">Notifications</button><button class="white-button" data-action="add-task">Create new +</button><button class="icon-button" data-action="demo-like" aria-label="Like">${icon('heart')}</button></div></div><div class="panel">${head('Status & badges','The right information at a glance.')}<div class="component-group">${badge('● Active')}${badge('In progress','orange')}${badge('Design system','purple')}${badge('Attention','red')}<span class="pill">⌘ K</span></div></div><div class="panel">${head('Progress & motion','Animated indicators with a little personality.')}<div class="component-group" style="justify-content:space-around"><div class="ring-progress"></div><div class="orb" style="transform:scale(.6);margin:-15px"><div class="orb-center"><small>FOCUS</small><strong>24m</strong></div></div></div>${progress(65)}</div><div class="panel">${head('Inputs & controls','Made to be touched and adjusted.')}<label class="setting-row"><span><strong>Focus mode</strong><p>Silence visual distractions</p></span><input type="checkbox" class="switch" data-demo-toggle="Focus mode"></label><label class="range-label" for="demo-volume">Volume <b id="demo-volume-label">65%</b></label><input id="demo-volume" type="range" value="65"></div><div class="panel">${head('Color system','One accent. Every surface.')} ${colorControls()}</div><div class="panel">${head('Expandable details','Everything has its place.')}<details class="accordion" open><summary>What is Glassy?</summary><p>A local, interactive recreation of your two references, extended with a workspace and a flexible color system.</p></details><details class="accordion"><summary>Where is my data stored?</summary><p>Your preferences, tasks and demo transactions are saved in this browser. No account or server is required.</p></details></div><div class="panel">${head('Loading states','A quiet shimmer while things get ready.')}<div class="skeleton" style="width:50%"></div><div class="skeleton" style="width:90%"></div><div class="skeleton" style="width:75%"></div></div><div class="panel">${head('Toasts & dialogs','Useful feedback, without the clutter.')}<div class="component-group">${action('Show toast','demo-save','secondary')}${action('Open dialog','add-goal','primary')}</div></div></div>`}
function settings(){return `<div class="grid two"><div class="panel">${head('Make it yours','Choose the color that feels like you.')} ${colorControls()}<label class="range-label" for="glass-blur">Glass blur <b id="blur-value">${prefs.blur}px</b></label><input id="glass-blur" type="range" min="0" max="50" value="${prefs.blur}"><label class="range-label" for="glass-opacity">Surface opacity <b id="opacity-value">${prefs.opacity}%</b></label><input id="glass-opacity" type="range" min="25" max="95" value="${prefs.opacity}"></div><div class="panel">${head('Your profile','Personal details, saved on this device.')}<form id="profile-form"><label class="field"><span>Display name</span><input name="name" value="${escapeHtml(prefs.name)}" maxlength="40" required style="font-size:14px"></label><button class="primary" type="submit">Save profile</button></form></div><div class="panel">${head('Experience','A comfortable space, on your terms.')}<label class="setting-row"><span><strong>Animations</strong><p>Soft entrances, drawing charts and ambient motion</p></span><input class="switch" type="checkbox" data-pref="motion" ${prefs.motion?'checked':''}></label><label class="setting-row"><span><strong>Compact layout</strong><p>A little more information, a little less space</p></span><input class="switch" type="checkbox" data-pref="compact" ${prefs.compact?'checked':''}></label><label class="setting-row"><span><strong>Notifications</strong><p>Show in-app notification indicators</p></span><input class="switch" type="checkbox" data-pref="notifications" ${prefs.notifications?'checked':''}></label></div><div class="panel">${head('Your local space','A functional prototype, with demonstration data.')}<p class="muted" style="font-size:11px;line-height:1.8">Finance, Creator, Gaming and Workspace live together here. Transactions, exchanges and game launches are simulations. Your preferences and workspace are saved in this browser.</p><div class="component-group">${action('Export my data','export-data','secondary')}${action('Reset appearance','reset-appearance','secondary')}</div></div></div>`}
const renderers={dashboard,cards,wallet,documents,transactions:transactionPage,analytics,studio,growth,revenue,gaming,library,achievements,tasks:taskPage,calendar:calendarPage,components,settings};
function applyPrefs(){document.documentElement.style.setProperty('--accent',prefs.accent);let hex=prefs.accent.replace('#','');document.documentElement.style.setProperty('--accent-rgb',[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)).join(','));document.documentElement.style.setProperty('--blur',prefs.blur+'px');document.documentElement.style.setProperty('--glass-opacity',prefs.opacity/100);document.body.classList.toggle('no-motion',!prefs.motion);document.body.classList.toggle('compact',prefs.compact);$('.notification-dot').style.display=prefs.notifications&&!notificationsRead?'':'none';save('preferences',prefs)}
function render(){const [title,,m]=pages[currentPage];mode=m;$('#page-title').textContent=title;$('#section-label').textContent={finance:'YOUR FINANCIAL OVERVIEW',creator:'CREATE. CONNECT. GROW.',gaming:'YOUR NEXT ADVENTURE AWAITS',workspace:'A LITTLE SPACE FOR GREAT IDEAS'}[mode];$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#nav-items').innerHTML=Object.entries(pages).filter(([id,p])=>p[2]===mode&&id!=='settings').map(([id,p])=>`<button class="nav-button ${id===currentPage?'active':''}" data-page="${id}" data-label="${p[0]}" aria-label="${p[0]}" ${id===currentPage?'aria-current="page"':''}>${icon(p[1])}</button>`).join('');$('#settings-icon').classList.toggle('active',currentPage==='settings');$('#profile-panel').style.display=mode==='finance'?'':'none';$('#profile-panel').innerHTML=profile();$('#main').innerHTML=`<div class="page-enter">${renderers[currentPage]()}</div>`;document.title=`${title} — Glassy`;if(currentPage==='wallet')updateSwap();}
function navigate(id){if(!pages[id])return;currentPage=id;history.replaceState(null,'','#'+id);render();if(window.innerWidth<700)window.scrollTo({top:0,behavior:prefs.motion?'smooth':'instant'});}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('check')+`<span>${escapeHtml(message)}</span>`;$('#toast-area').append(el);setTimeout(()=>el.remove(),4200)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#modal-content input')?.focus(),40)}
function closeModal(){$('#modal').close()}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function inputField(label,name,type='text',value='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${escapeHtml(value)}" required ${extra}></label>`}
function taskModal(tag='Design'){modal(`<h2>A little idea. A new task.</h2><p>Give your next piece of work a home.</p><form id="task-form">${inputField('Task name','title','text','', 'maxlength="80"')}${inputField('Description','description','text','', 'maxlength="160"')}<label class="field"><span>Category</span><select name="tag">${['Design','Content','Finance','Product'].map(t=>`<option ${tag===t?'selected':''}>${t}</option>`).join('')}</select></label>${inputField('Due date','date','date','2026-10-12')}<button class="primary full">Create task</button></form>`)}
function appearanceModal(){modal(`<h2>Your kind of glass.</h2><p>Change the accent across every screen, chart and control.</p>${colorControls()}<button class="secondary full" data-action="full-settings">More appearance settings →</button>`)}
function notifications(){notificationsRead=true;save('notifications-read',true);applyPrefs();modal(`<h2>Notifications</h2><p>You're all caught up with your space.</p>${[['chart','Your savings are growing','Business savings increased by 12.8% this month.'],['play','A new milestone','Your channel reached 76,000 users.'],['calendar','Design review','Your review is on the calendar for October 10.']].map(([i,n,d])=>`<div class="notification-item">${icon(i)}<div><strong>${n}</strong><p>${d}</p></div></div>`).join('')}`)}
function search(){modal(`<h2>Where would you like to go?</h2><label class="field"><input id="global-search" type="search" placeholder="Search your spaces…" aria-label="Search pages"></label><div class="search-results" id="search-results">${searchRows('')}</div>`)}
function searchRows(query){return Object.entries(pages).filter(([id,p])=>(p[0]+' '+p[2]).toLowerCase().includes(query.toLowerCase())).map(([id,p])=>`<button class="search-result" data-search-page="${id}">${icon(p[1])}${p[0]}<small>${p[2]}</small></button>`).join('')||'<div class="empty-state">No matching spaces.</div>'}
function transferModal(type){let title={transfer:'Send a little something.',receive:'Your receiving details',bill:'Pay a bill', 'top-up':'Top up your balance'}[type];if(type==='receive'){modal(`<h2>${title}</h2><p>Demo account details for this prototype.</p><div class="panel"><small class="muted">ACCOUNT HOLDER</small><h3 style="margin:10px 0 20px">${escapeHtml(prefs.name)}</h3><small class="muted">DEMO ACCOUNT NUMBER</small><h3 style="margin-top:10px">GLSY 2026 0000 8824</h3></div><button class="primary full spaced" data-action="copy-account">Copy account details</button>`);return}modal(`<h2>${title}</h2><p>This is a local simulation. No real payment will be made.</p><form id="payment-form" data-type="${type}">${inputField(type==='bill'?'Bill or provider':type==='top-up'?'Source':'Recipient','recipient','text','', 'maxlength="60"')}${inputField('Amount (USD)','amount','number','', 'min="0.01" max="100000" step="0.01"')}<button class="primary full">${type==='top-up'?'Add demo funds':'Confirm demo payment'}</button></form>`)}
function updateSwap(){const rates={USD:1,BTC:92000,ETH:3550,SOL:152},amount=Number($('#swap-pay')?.value),from=$('#swap-from')?.value,to=$('#swap-to')?.value;if($('#swap-receive'))$('#swap-receive').value=Number.isFinite(amount)&&amount>=0?(amount*rates[from]/rates[to]).toFixed(to==='USD'?2:6):'0';}
const actions={appearance:appearanceModal,notifications,search,'full-settings':()=>{closeModal();navigate('settings')},transfer:()=>transferModal('transfer'),receive:()=>transferModal('receive'),bill:()=>transferModal('bill'),'top-up':()=>transferModal('top-up'),'view-studio':()=>navigate('studio'),'add-task':()=>taskModal(),'content-task':()=>taskModal('Content'),'add-goal':()=>modal(`<h2>Something to look forward to.</h2><p>Create a new savings goal.</p><form id="goal-form">${inputField('Goal name','name','text','', 'maxlength="60"')}${inputField('Target amount (USD)','target','number','5000','min="1" step="0.01"')}${inputField('Already saved (USD)','saved','number','0','min="0" step="0.01"')}<button class="primary full">Create goal</button></form>`),'reverse-swap':()=>{const a=$('#swap-from').value;$('#swap-from').value=$('#swap-to').value;$('#swap-to').value=a;updateSwap()},swap:()=>{let n=Number($('#swap-pay').value);if(!Number.isFinite(n)||n<=0){toast('Enter an amount greater than zero.');return}toast(`Demo exchange: ${n} ${$('#swap-from').value} → ${$('#swap-receive').value} ${$('#swap-to').value}. No funds moved.`)},'upload-document':()=>{uploadKind='document';$('#file-input').accept='.pdf,.csv,.txt,.png,.jpg,.jpeg';$('#file-input').click()},'upload-video':()=>{uploadKind='video';$('#file-input').accept='video/*';$('#file-input').click()},'export-transactions':()=>{download('glassy-transactions.csv','Name,Details,Amount,Category\n'+transactions.map(t=>[t.name,t.detail,t.amount,t.type].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv');toast('Transactions exported.')},withdraw:()=>{let available=586-withdrawn;if(available<=0){toast('No demo funds available for payout.');return}modal(`<h2>Withdraw funds</h2><p>Available: ${money(available)}. This payout is a local simulation.</p><form id="withdraw-form">${inputField('Amount (USD)','amount','number',String(available),`min="0.01" max="${available}" step="0.01"`)}<button class="primary full">Confirm demo payout</button></form>`)},'add-event':()=>modal(`<h2>Make a little time.</h2><p>Add a moment to your calendar.</p><form id="event-form">${inputField('Event name','title','text','','maxlength="60"')}${inputField('Date','date','date',`${year}-${String(month+1).padStart(2,'0')}-${String(selectedDay).padStart(2,'0')}`)}${inputField('Time','time','time','10:00')}<button class="primary full">Add event</button></form>`),'demo-save':()=>toast('Changes saved. Looking good.'),'demo-like':e=>{const b=e.closest('button');let liked=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',liked);b.style.color=liked?'var(--accent)':'';toast(liked?'Added to your favorites.':'Removed from favorites.')},'reset-appearance':()=>{prefs={...prefs,accent:defaults.accent,blur:28,opacity:64,motion:true,compact:false};applyPrefs();render();toast('Original orange appearance restored.')},'export-data':()=>download('glassy-local-data.json',JSON.stringify({preferences:prefs,tasks,events,documents:docs,transactions,videos,goals:customGoals},null,2),'application/json'),'copy-account':async()=>{try{await navigator.clipboard.writeText(`${prefs.name} · GLSY 2026 0000 8824`);toast('Demo account details copied.')}catch{toast('Account: GLSY 2026 0000 8824')}},'download-toggle':()=>{if(downloadProgress>=100){toast('FIFA 23 is ready in this demo.');return}downloadPaused=!downloadPaused;render()}};
let uploadKind='document';
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.page)navigate(b.dataset.page);if(b.dataset.mode)navigate({finance:'dashboard',creator:'analytics',gaming:'gaming',workspace:'tasks'}[b.dataset.mode]);if(b.dataset.action)actions[b.dataset.action]?.(b);if(b.dataset.card!==undefined){selectedCard=Number(b.dataset.card);render()}if(b.dataset.docFilter){docFilter=b.dataset.docFilter;render()}if(b.dataset.videoFilter){videoFilter=b.dataset.videoFilter;render()}if(b.dataset.gameFilter){gameFilter=b.dataset.gameFilter;render()}if(b.dataset.period){period=b.dataset.period;render()}if(b.dataset.color){prefs.accent=b.dataset.color;applyPrefs();$$('.swatch').forEach(s=>{s.classList.toggle('selected',s.dataset.color===prefs.accent);s.setAttribute('aria-pressed',s.dataset.color===prefs.accent)});$$('[data-custom-accent]').forEach(s=>s.value=prefs.accent)}if(b.dataset.searchPage){closeModal();navigate(b.dataset.searchPage)}if(b.dataset.document!==undefined){const d=docs[Number(b.dataset.document)];download(d.name.replace(/[^a-z0-9\- ]/gi,'')+'.txt',`GLASSY — DEMONSTRATION RECORD\n\n${d.name}\nDate: ${d.date}\nAmount: ${money(d.amount)}\nStatus: ${d.status}\nCategory: ${d.category}\n\nThis is a generated demo summary, not an original financial document.`);toast('Demo record downloaded.')}if(b.dataset.video!==undefined){let v=videos[Number(b.dataset.video)];modal(`<h2>${escapeHtml(v.title)}</h2><p>${v.category} · Video performance</p>${summary([['Views',v.views],['CTR',v.ctr],['Revenue',money(v.revenue)]])}<div class="panel">${head('Average view duration',v.retention)}${progress(parseFloat(v.retention.split('(')[1])||0)}</div>`)}if(b.dataset.game){modal(`<h2>${escapeHtml(b.dataset.game)}</h2><p>Your gaming space, brought to life. This interface is a demo launcher; no game is installed or launched.</p><div class="panel">${head('Ready for your next adventure','Explore your library, track your time and celebrate every achievement.')}<div class="component-group">${badge('Adventure','orange')}${badge('In your collection')}</div></div><button class="primary full spaced" data-action="open-library">Explore library</button>`)}if(b.dataset.friend){modal(`<h2>${escapeHtml(b.dataset.friend)} is online</h2><p>Playing Elden Ring · Demo friend profile</p><button class="primary full" data-action="invite-friend">Send demo invite</button>`)}if(b.dataset.month){month+=Number(b.dataset.month);if(month<0){month=11;year--}if(month>11){month=0;year++}selectedDay=1;render()}if(b.dataset.day){selectedDay=Number(b.dataset.day);render()}if(b.dataset.deleteTask){tasks=tasks.filter(t=>t.id!==Number(b.dataset.deleteTask));save('tasks',tasks);render();toast('Task removed.')}if(b.dataset.deleteEvent){events=events.filter(t=>t.id!==Number(b.dataset.deleteEvent));save('events',events);render();toast('Event removed.')}});
actions['open-library']=()=>{closeModal();navigate('library')};actions['invite-friend']=()=>{closeModal();toast('Demo invitation sent. No external message was sent.')};
document.addEventListener('input',e=>{const el=e.target;if(el.id==='spending-limit'){cardSettings[selectedCard].limit=Number(el.value);$('#limit-value').textContent=money(Number(el.value));save('cards',cardSettings)}if(el.dataset.customAccent){prefs.accent=el.value;applyPrefs();$$('.swatch').forEach(s=>s.classList.remove('selected'))}if(el.id==='glass-blur'){prefs.blur=Number(el.value);$('#blur-value').textContent=el.value+'px';applyPrefs()}if(el.id==='glass-opacity'){prefs.opacity=Number(el.value);$('#opacity-value').textContent=el.value+'%';applyPrefs()}if(el.id==='global-search')$('#search-results').innerHTML=searchRows(el.value);if(el.id==='transaction-search')$('#transaction-list').innerHTML=transactionRows(transactions.filter(t=>(t.name+' '+t.type+' '+t.amount).toLowerCase().includes(el.value.toLowerCase())));if(el.id==='swap-pay')updateSwap();if(el.id==='demo-volume')$('#demo-volume-label').textContent=el.value+'%'});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.cardSetting){cardSettings[selectedCard][el.dataset.cardSetting]=el.checked;save('cards',cardSettings);toast('Card preference saved.')}if(el.dataset.pref){prefs[el.dataset.pref]=el.checked;applyPrefs()}if(el.dataset.demoToggle)toast(`${el.dataset.demoToggle} ${el.checked?'enabled':'disabled'}.`);if(el.dataset.taskStatus){const t=tasks.find(t=>t.id===Number(el.dataset.taskStatus));if(t)t.status=el.value;save('tasks',tasks);render()}if(['swap-from','swap-to'].includes(el.id))updateSwap();if(el.id==='growth-period'){period=el.value;render()}if(el.id==='chart-type'){chartType=el.value;period=chartType==='Income'?'1M':chartType==='Expenses'?'1Y':'6M';render()}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));if(form.id==='profile-form'){prefs.name=data.name.trim()||defaults.name;applyPrefs();render();toast('Profile saved.');return}if(form.id==='task-form'){tasks.push({id:Date.now(),title:data.title.trim(),description:data.description.trim(),tag:data.tag,date:new Date(data.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'2-digit'}),status:'todo'});save('tasks',tasks);closeModal();navigate('tasks');toast('Task created.')}if(form.id==='goal-form'){if(Number(data.saved)>Number(data.target)){toast('Saved amount cannot exceed the goal target.');return}customGoals.push({name:data.name.trim(),target:Number(data.target),saved:Number(data.saved)});save('goals',customGoals);closeModal();navigate('dashboard');toast('Savings goal created.')}if(form.id==='payment-form'){const type=form.dataset.type;transactions.unshift({name:data.recipient.trim(),detail:'Local demo · Just now',amount:Number(data.amount)*(type==='top-up'?1:-1),type:type==='top-up'?'Income':type==='bill'?'Bill':'Transfer'});save('transactions',transactions);closeModal();navigate('transactions');toast('Demo transaction recorded. No real money moved.')}if(form.id==='withdraw-form'){const amount=Number(data.amount);if(!Number.isFinite(amount)||amount<=0||amount>586-withdrawn)return;withdrawn+=amount;save('withdrawn',withdrawn);closeModal();render();toast('Demo payout recorded. No real funds moved.')}if(form.id==='event-form'){events.push({id:Date.now(),title:data.title.trim(),date:data.date,time:data.time,type:'Personal'});save('events',events);const parts=data.date.split('-').map(Number);year=parts[0];month=parts[1]-1;selectedDay=parts[2];closeModal();navigate('calendar');toast('Event added to your local calendar.')}});
$('#file-input').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(uploadKind==='document'){docs.unshift({name:file.name,date:new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),size:file.size>1048576?(file.size/1048576).toFixed(1)+' MB':Math.ceil(file.size/1024)+' KB',amount:0,status:'Local',category:'Expense Invoices'});save('documents',docs);docFilter='All Documents';navigate('documents');toast('Document name added locally. Original file remains on your device.')}else{videos.unshift({title:file.name.replace(/\.[^.]+$/,''),category:'Sport Series',views:'0',ctr:'0%',retention:'00:00 (0%)',revenue:0});save('videos',videos);videoFilter='All';navigate('studio');toast('Video added to the local demo list. No upload was sent.')}e.target.value=''});
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-task]');if(el)e.dataTransfer.setData('text/plain',el.dataset.task)});document.addEventListener('dragover',e=>{const col=e.target.closest('[data-status]');if(col){e.preventDefault();col.classList.add('drag-over')}});document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-status]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over')});document.addEventListener('drop',e=>{const col=e.target.closest('[data-status]');if(col){e.preventDefault();const t=tasks.find(t=>t.id===Number(e.dataTransfer.getData('text/plain')));if(t){t.status=col.dataset.status;save('tasks',tasks);render()}}});
$('.modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}});window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(pages[p])navigate(p)});
setInterval(()=>{if(!downloadPaused&&downloadProgress<100){downloadProgress=Math.min(100,downloadProgress+2);if($('#download-percent'))$('#download-percent').textContent=downloadProgress;if($('#download-bar'))$('#download-bar').style.width=downloadProgress+'%';if(downloadProgress===100){downloadPaused=true;if(currentPage==='gaming')render();toast('FIFA 23 demo download complete.')}}},1100);
$('#bell-icon').innerHTML=icon('bell');$('#settings-icon').innerHTML=icon('settings');applyPrefs();navigate(pages[location.hash.slice(1)]?location.hash.slice(1):'dashboard');
